arguments.command:
python3 << 'EOF'
gold = "PNPNNNNPNNNNNNPNNNNPNNNNNNPNNNNPNPNNNNNNNNNNNNNNNNNNNPNNNNNNPNNNNPNNNNNNPNNNNPNPNNNNPNNNNNNNNNNNNNNNNNNPNNNNNNNNNNNNPNNNNNNNNNNNNNP"

responses = {
    "A": None,  # Not a real string
    "B": None,  # No string
    "C": "PNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNN",
    "D": "PNNNPPPNNPPNNNPPNNPPPNNPPNPPNPPNPPNPPNPPNPPNPPNPPNPPNPPNPPNPPNPPNPPN",
    "E": "NNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPNNPN",
    "F": "PNPNNNNPNNNPNPNNNNNPNNNPNNNNNPNPNNNNNPNNNPNNNNNPNNN",
    "G": "PNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNN",
    "H": "PNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNPNP"
}

print(f"Gold length: {len(gold)}")
print()

for resp_id, resp_str in responses.items():
    if resp_str:
        print(f"Response {resp_id}: length {len(resp_str)}")
        if len(resp_str) == 131:
            matches = sum(1 for a, b in zip(gold, resp_str) if a == b)
            print(f"  Matches gold: {matches}/131")
            if matches < 131:
                # Find first mismatch
                for i, (a, b) in enumerate(zip(gold, resp_str)):
                    if a != b:
                        print(f"  First mismatch at index {i}: gold={a}, resp={b}")
                        break
        print()

# Check if any response matches gold exactly
print("Exact matches:")
for resp_id, resp_str in responses.items():
    if resp_str == gold:
        print(f"  {resp_id}: EXACT MATCH")
    elif resp_str:
        print(f"  {resp_id}: NO MATCH")
    else:
        print(f"  {resp_id}: No valid string")
EOF

